import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/ko/ermaster-open-demo.png",s="/relio/shots/ko/ermaster-target-version.png",g=JSON.parse('{"title":"ERMaster에서 넘어오기","description":"","frontmatter":{},"headers":[],"relativePath":"quick/from-ermaster.md","filePath":"quick/from-ermaster.md"}'),l={name:"quick/from-ermaster.md"};function c(n,e,d,m,p,f){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="ermaster에서-넘어오기" tabindex="-1">ERMaster에서 넘어오기 <a class="header-anchor" href="#ermaster에서-넘어오기" aria-label="Permalink to &quot;ERMaster에서 넘어오기&quot;">​</a></h1><p>Relio는 ERMaster와 같은 <code>.erm</code> 파일을 씁니다. 변환할 것 없이 열고, 저장한 파일은 ERMaster에서도 열립니다. 팀에 ERMaster를 쓰는 사람이 있어도 함께 쓸 수 있습니다.</p><ol><li><p><strong>열기</strong> — 파일 › 열기(<kbd>Ctrl</kbd>+<kbd>O</kbd>)로 고르거나 <code>.erm</code> 파일을 창에 끌어다 놓습니다. 여러 파일은 탭으로 열립니다.</p><figure class="shot" data-scene="ermaster-open-demo"><img src="'+i+'" alt="ERMaster로 만든 .erm 파일을 Relio에서 연 모습" loading="lazy"><figcaption>ERMaster로 만든 .erm 파일을 Relio에서 연 모습</figcaption></figure></li><li><p><strong>대상 DB 버전 고르기</strong> — 상태 표시줄 맨 왼쪽(예: &quot;PostgreSQL 16&quot;)을 눌러 실제로 쓰는 DB 버전을 고릅니다. 설계 검사와 DDL이 그 버전 문법을 따릅니다. 모르면 그대로 두어도 됩니다.</p><figure class="shot" data-scene="ermaster-target-version"><img src="'+s+'" alt="상태 표시줄에서 대상 DB 버전을 고르는 창" loading="lazy"><figcaption>상태 표시줄에서 대상 DB 버전을 고르는 창</figcaption></figure></li><li><p><strong>저장</strong> — <kbd>Ctrl</kbd>+<kbd>S</kbd>. 저장은 임시 파일에 다 쓴 뒤 바꿔 넣으므로 저장 중에 꺼져도 원래 파일이 깨지지 않습니다.</p></li></ol><h2 id="섞어-써도-되는-이유" tabindex="-1">섞어 써도 되는 이유 <a class="header-anchor" href="#섞어-써도-되는-이유" aria-label="Permalink to &quot;섞어 써도 되는 이유&quot;">​</a></h2><ul><li>Relio는 테이블을 늘 내용에 맞는 크기로 그리지만, 파일에 적힌 크기·위치는 그대로 둡니다. 열고 저장한 것만으로 차이가 생기지 않습니다.</li><li>대상 DB 버전, 설계 검사 예외처럼 Relio에만 있는 설정은 <code>.erm</code>이 아니라 이 PC에 파일마다 기억합니다.</li><li>여러 카테고리를 함께 본 상태는 파일에 남기지 않고, 마지막에 고른 카테고리 하나만 남깁니다.</li></ul><h2 id="달라진-점" tabindex="-1">달라진 점 <a class="header-anchor" href="#달라진-점" aria-label="Permalink to &quot;달라진 점&quot;">​</a></h2><ul><li>Eclipse 없이 혼자 실행됩니다.</li><li>Excel 출력은 <code>.xlsx</code>입니다. ERMaster <code>.xls</code> 템플릿은 그대로 쓸 수 있습니다.</li><li>DB 암호는 기본으로 <code>.erm</code>이 아니라 Windows 자격 증명 관리자에 저장합니다.</li><li>Relio에만 있는 형식(예: <code>json</code>)을 쓴 컬럼은 ERMaster에서 형식이 비어 보입니다. <a href="/relio/features/troubleshooting#ermaster에서-형식이-비어-보일-때">자세히</a></li><li>DB별로 실행 오류가 나던 DDL 문법, 테스트 데이터 SQL의 따옴표·빈 값 같은 알려진 문제를 고쳤습니다.</li><li>설계 검사, 입력 중 추천, 한글 초성 찾기, 모델 단위 합치기가 더해졌습니다.</li></ul><div class="warning custom-block"><p class="custom-block-title">주의</p><p>ERMaster와 Relio를 섞어 쓰는 팀이 Git을 쓴다면 줄 끝 설정을 먼저 맞추세요. 그렇지 않으면 저장할 때마다 파일 전체가 바뀐 것으로 잡힐 수 있습니다. <a href="/relio/quick/git#저장소-준비">Git으로 함께 쓰기</a>를 보세요.</p></div><p><strong>자세히</strong> → <a href="/relio/features/file">파일</a> · <a href="/relio/features/ddl">DDL</a> · <a href="/relio/features/import">가져오기와 다른 형식</a> · <a href="/relio/features/troubleshooting#ermaster에서-형식이-비어-보일-때">ERMaster에서 형식이 비어 보일 때</a></p>',9)])])}const h=r(l,[["render",c]]);export{g as __pageData,h as default};
